const samples=[{label:'고객 응대 초안 검수',text:'고객 문의와 기존 응대 초안을 대조하는 검수 에이전트를 만들어줘. 정책은 연결한 문서를 사용하고, 없으면 정책을 추정하지 마세요. 문제 유형·심각도·문제 구절·수정안을 보고하고 운영자가 수정·승인 또는 거절하게 해줘. 단일 문의와 초안은 실행 화면에서 입력할게요. 예약은 필요 없어요.'},{label:'예약 재고 보고서',text:'매일 오전 9시에 재고가 기준 수량보다 적은 상품을 찾아 보고서로 저장해줘.'},{label:'주간 목록 집계',text:'매주 월요일 오전 9시 한국 시간에 신청서 목록을 상태별 건수로 집계해서 A4B 보고서 보관함에 CSV로 저장해줘. 신청서는 연결한 파일을 관리 데이터 소스로 사용하고, 상태가 비어 있으면 별도 빈 값 그룹으로 집계해주세요.'},{label:'문서에서 응대 초안 만들기',text:'연결한 정책 문서를 읽고 고객 문의에 대한 응대 초안을 만드는 에이전트를 구성해줘. 정책에 없는 사실이나 처리 완료는 추정하지 않고 부족한 정보는 명시해줘. 고객 문의는 실행 화면에서 입력할게. 예약이나 외부 전송은 필요 없어요.'},{label:'CSV 문의 현황 정리하기',text:'연결한 CSV의 실제 열을 확인하고 상태별 문의 건수를 집계해서 CSV로 내려받는 흐름을 만들어줘. 중복 행과 빈 값은 유지하고 집계는 처리 노드로 실행해줘. 예약은 필요 없어요.'}];
async function asBase64(file:File){return new Promise<string>((accept,reject)=>{const reader=new FileReader();reader.onload=()=>accept(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('파일을 읽지 못했습니다.'));reader.readAsDataURL(file);});}
function download(artifact:{name:string;content:string;mime:string}){const url=URL.createObjectURL(new Blob([artifact.content],{type:artifact.mime}));const a=document.createElement('a');a.href=url;a.download=artifact.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
